INSERT INTO scans (id,owner_id,status,source,image_key,image_content_type,image_bytes,image_width,image_height,problem_text,created_at,updated_at,confirmed_at,questions_json) VALUES ('60837e4e-a3f2-4778-852c-a9728b0cfaaf','732f08f52de70f60b84de094e1b9fd02778bf043e1b11f334c8094967a39867c','confirmed','library','game-theory-02/no-upload/60837e4e-a3f2-4778-852c-a9728b0cfaaf','image/png',1,1,1,'Cho bàn cờ $2\times15$. An chọn một ô ban đầu, sau đó mỗi lượt An di chuyển sang một ô kề bên. Bình chọn $k$ ô mỗi lượt để hỏi An. Chứng minh Bình có thể thắng sau không quá 14 lượt với $k=4$ và không quá 28 lượt với $k=2$.','2026-10-12T07:38:10.034905+00:00','2026-10-12T07:38:10.034905+00:00','2026-10-12T07:38:10.034905+00:00','[{"id": "q1", "label": "Bài kiểm tra", "text": "Cho bàn cờ $2\\times15$. An chọn một ô ban đầu, sau đó mỗi lượt An di chuyển sang một ô kề bên. Bình chọn $k$ ô mỗi lượt để hỏi An. Chứng minh Bình có thể thắng sau không quá 14 lượt với $k=4$ và không quá 28 lượt với $k=2$."}]');
